insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id)
select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id
from jsonb_to_recordset($json$[{"id":"che-ek-245","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A first-order gas reaction has $k = 1.386 \\times 10^{-2}\\ \\mathrm{min^{-1}}$. Its half-life is","options":["50 min","0.693 min","72 min","100 min"],"answer_index":0,"explanation":"$t_{1/2} = 0.693/k = 0.693/(1.386 \\times 10^{-2}) = 50\\ \\mathrm{min}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-246","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"If 60% of a first-order reactant remains after 20 min, the leftover fraction after a further 20 min is nearest","options":["0.36","0.60","0.16","0.48"],"answer_index":0,"explanation":"First order: the same time interval multiplies [A] by the same factor 0.60, so $0.60 \\times 0.60 = 0.36$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-247","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"How long does a first-order reaction of half-life 15 min take to reach 75% completion?","options":["30 min","15 min","45 min","7.5 min"],"answer_index":0,"explanation":"75% completion is two half-lives, so $2 \\times 15 = 30\\ \\mathrm{min}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-248","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"From a measured first-order half-life of 46.2 min one obtains $k$ equal to","options":["$1.50 \\times 10^{-2}\\ \\mathrm{min^{-1}}$","$46.2\\ \\mathrm{min^{-1}}$","$0.693\\ \\mathrm{min^{-1}}$","$3.00 \\times 10^{-2}\\ \\mathrm{min^{-1}}$"],"answer_index":0,"explanation":"$k = 0.693/t_{1/2} = 0.693/46.2 = 1.50 \\times 10^{-2}\\ \\mathrm{min^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-249","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A zero-order reaction with $k = 2.0 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ min^{-1}}$ and $[\\mathrm{A}]_0 = 0.20\\ \\mathrm{M}$ is complete after","options":["100 min","50 min","200 min","0.10 min"],"answer_index":0,"explanation":"Completion means $[\\mathrm{A}] = 0$, so $t = [\\mathrm{A}]_0/k = 0.20/(2.0 \\times 10^{-3}) = 100\\ \\mathrm{min}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-250","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Starting from a first-order sample, the number of half-lives needed to leave only one-eighth of the reactant is","options":["3","2","4","8"],"answer_index":0,"explanation":"$(1/2)^n = 1/8$ gives $n = 3$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-251","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For 2A → products, $k = 0.50\\ \\mathrm{L\\ mol^{-1}\\ min^{-1}}$ and $[\\mathrm{A}]_0 = 0.20\\ \\mathrm{M}$. The half-life is","options":["10 min","1.4 min","0.10 min","20 min"],"answer_index":0,"explanation":"$t_{1/2} = 1/(k[\\mathrm{A}]_0) = 1/(0.50 \\times 0.20) = 10\\ \\mathrm{min}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-252","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A first-order isomerisation has $t_{1/2} = 20\\ \\mathrm{min}$. The time required for 87.5% conversion is","options":["60 min","40 min","20 min","80 min"],"answer_index":0,"explanation":"87.5% converted leaves 12.5% = $1/8$, which is three half-lives: $3 \\times 20 = 60\\ \\mathrm{min}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-253","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Half-life of a gaseous decay is 40 min at 0.80 bar initial pressure and 80 min at 0.40 bar. The order and $k$ (from the 0.80 bar run, treating concentration as proportional to $p$) are consistent with","options":["second order, because $t_{1/2}$ doubles when $p_0$ is halved","first order, because $t_{1/2}$ is independent of $p_0$","zero order, because $t_{1/2}$ halves when $p_0$ is halved","third order, because $t_{1/2} \\propto p_0^2$"],"answer_index":0,"explanation":"Second-order $t_{1/2} \\propto 1/[\\mathrm{A}]_0$. Halving the initial pressure doubles the half-life, which matches the data.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-254","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A first-order hydrolysis has $k = 2.303 \\times 10^{-3}\\ \\mathrm{s^{-1}}$. The percentage of reactant still left after 1000 s is nearest","options":["10%","50%","1%","90%"],"answer_index":0,"explanation":"$\\log([\\mathrm{A}]_0/[\\mathrm{A}]) = kt/2.303 = 1.00$, so $[\\mathrm{A}]/[\\mathrm{A}]_0 = 0.10$ (10% remains).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-255","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Activation energy $E_a$ of a reaction is the","options":["minimum extra energy that colliding molecules must possess if they are to react","heat released when products form","same quantity as $\\Delta H$ of the reaction","Faraday constant multiplied by $T$"],"answer_index":0,"explanation":"$E_a$ is the barrier height on the reaction profile. Only collisions that clear that barrier can form products.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-256","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a typical activated reaction, raising the temperature causes the rate constant to","options":["increase","decrease toward zero","become equal to the Faraday constant","lose its units"],"answer_index":0,"explanation":"The Boltzmann factor $e^{-E_a/RT}$ grows as $T$ grows, so $k$ rises (often steeply).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
